const input = $input.first().json ?? {};

function optionalPositiveInteger(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const number = Number(value);

  return Number.isInteger(number) && number > 0
    ? number
    : null;
}

function parseObject(value) {
  if (!value) {
    return {};
  }

  if (typeof value === 'object') {
    return value;
  }

  try {
    return JSON.parse(value);
  } catch {
    return {};
  }
}

const usecaseId = optionalPositiveInteger(input.usecase_id);
const userId = optionalPositiveInteger(input.user_id);
const mappingId = optionalPositiveInteger(input.user_mapping_id);

const message = String(input.message ?? '').trim();
const warnings = [];

if (!message) {
  warnings.push('No mapping-design request was provided.');
}

if (!usecaseId) {
  warnings.push('No valid use case ID was provided.');
}

return [{
  json: {
    valid: Boolean(message && usecaseId),

    session_id:
      String(input.session_id ?? '').trim() ||
      'missing-session',

    message,

    usecase_id: usecaseId,

    usecase_name:
      String(input.usecase_name ?? '').trim() ||
      null,

    user_id: userId,
    user_mapping_id: mappingId,

    context: parseObject(input.context),

    input_warnings: warnings
  }
}];

const input = $input.first().json;

return [{
  json: {
    expert: 'mapping_design',
    success: false,
    reply:
      'The Mapping Design Expert needs a request and a selected use case before it can prepare proposals.',

    session_id: input.session_id,
    citations: [],
    warnings: input.input_warnings ?? [],
    proposals: [],
    recommended_actions: []
  }
}];

const row = $input.first().json ?? {};
const request =
  $('Normalize Mapping Request').first().json ?? {};

function parseJsonValue(value, fallback) {
  if (value === null || value === undefined) {
    return fallback;
  }

  if (typeof value === 'object') {
    return value;
  }

  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}

const currentMappings = parseJsonValue(
  row.current_mappings,
  []
);

const sensorStatistics = parseJsonValue(
  row.sensor_statistics,
  {}
);

const selectedUserMapping = parseJsonValue(
  row.selected_user_mapping,
  null
);

const warnings = [
  ...(request.input_warnings ?? [])
];

if (!row.usecase_id) {
  warnings.push(
    'Use case ' + request.usecase_id + ' was not found.'
  );
}

if (!Array.isArray(currentMappings) || currentMappings.length === 0) {
  warnings.push(
    'No active mappings were found for the selected use case.'
  );
}

const totalReadings = Number(
  sensorStatistics?.total_readings ?? 0
);

function textIncludesAny(text, words) {
  const normalized = String(text ?? '').toLowerCase();

  return words.some(word =>
    normalized.includes(word)
  );
}

function numberOrNull(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const number = Number(value);

  return Number.isFinite(number)
    ? number
    : null;
}

const selectedMapping =
  selectedUserMapping?.mapping &&
  typeof selectedUserMapping.mapping === 'object' &&
  !Array.isArray(selectedUserMapping.mapping)
    ? selectedUserMapping.mapping
    : null;

const messageText = [
  request.message,
  request.context?.last_user_message,
  request.context?.app_context?.last_user_message
].filter(Boolean).join(' ');

const asksAboutValues = textIncludesAny(messageText, [
  'average',
  'avg',
  'mean',
  'logged value',
  'logged values',
  'reading',
  'readings',
  'sensor value',
  'sensor values',
  'threshold',
  'thresholds',
  'range',
  'min value',
  'max value',
  'minvalue',
  'maxvalue',
  'lower bound',
  'upper bound',
  'tighten'
]);

const asksToUpdateCurrentMapping = textIncludesAny(messageText, [
  'update',
  'modify',
  'change this mapping',
  'change current mapping',
  'edit current mapping',
  'adjust current mapping',
  'refine current mapping',
  'this mapping',
  'mapping 140',
  'id 140'
]);

const asksForNewMapping = textIncludesAny(messageText, [
  'new mapping',
  'new mappings',
  'alternative mapping',
  'alternative mappings',
  'another mapping',
  'create mapping',
  'propose mapping',
  'propose mappings',
  'suggest mapping',
  'suggest mappings',
  'design mapping',
  'design mappings'
]);

const asksAboutBurden = textIncludesAny(messageText, [
  'feedback burden',
  'burden',
  'too much feedback',
  'too frequent',
  'frequency',
  'annoying',
  'intrusive',
  'interruption',
  'gentle',
  'stronger',
  'weaker',
  'intensity',
  'pulse',
  'pulses',
  'duration',
  'interval',
  'vibration'
]);

const minValue = numberOrNull(selectedMapping?.minvalue);
const maxValue = numberOrNull(selectedMapping?.maxvalue);
const avgSeen = numberOrNull(sensorStatistics?.avg_seen);
const minSeen = numberOrNull(sensorStatistics?.min_seen);
const maxSeen = numberOrNull(sensorStatistics?.max_seen);

const averageInsideCurrentRange =
  minValue !== null &&
  maxValue !== null &&
  avgSeen !== null
    ? avgSeen >= minValue && avgSeen <= maxValue
    : null;

const readingsOutsideCurrentRange =
  minValue !== null &&
  maxValue !== null &&
  (minSeen !== null || maxSeen !== null)
    ? (
        minSeen !== null && minSeen < minValue
      ) || (
        maxSeen !== null && maxSeen > maxValue
      )
    : null;

const requestedBasis =
  asksAboutValues
    ? 'recent_value_distribution'
    : asksAboutBurden
      ? 'feedback_burden_or_noticeability'
      : 'researcher_request';

const primaryCriteriaToConsider =
  requestedBasis === 'recent_value_distribution'
    ? ['minvalue', 'maxvalue']
    : requestedBasis === 'feedback_burden_or_noticeability'
      ? [
          'minpulses',
          'maxpulses',
          'minintensity',
          'maxintensity',
          'minduration',
          'maxduration',
          'mininterval',
          'maxinterval'
        ]
      : [
          'minvalue',
          'maxvalue',
          'minpulses',
          'maxpulses',
          'minintensity',
          'maxintensity',
          'minduration',
          'maxduration',
          'mininterval',
          'maxinterval'
        ];

const mappingAdjustmentGuidance = {
  requested_basis: requestedBasis,
  primary_criteria_to_consider: primaryCriteriaToConsider,
  current_mapping_threshold_fit: {
    selected_mapping_id:
      selectedMapping?.id ??
      selectedUserMapping?.mapping_id ??
      null,
    minvalue: minValue,
    maxvalue: maxValue,
    avg_seen: avgSeen,
    min_seen: minSeen,
    max_seen: maxSeen,
    average_inside_current_range: averageInsideCurrentRange,
    readings_outside_current_range: readingsOutsideCurrentRange
  },
  requested_update_to_current_mapping:
    asksToUpdateCurrentMapping && !asksForNewMapping,
  requested_new_mapping_alternative:
    asksForNewMapping,
  heart_rate_140_update_policy:
    Number(selectedMapping?.id ?? selectedUserMapping?.mapping_id ?? 0) === 140
      ? {
          applies: true,
          rule: 'If the proposal is an update to existing mapping ID 140, preserve its heart-rate-mirroring behavior by modifying only minintensity and/or maxintensity. Do not change minvalue, maxvalue, pulses, duration, or interval for an update to mapping 140. If the researcher asks for value-threshold changes, propose a new alternative mapping instead of an update to mapping 140.'
        }
      : {
          applies: false
        },
  instruction:
    requestedBasis === 'recent_value_distribution'
      ? 'When the researcher asks for changes based on averages, logged values, ranges, or thresholds, evaluate the values against the current mapping and primarily change minvalue and/or maxvalue for a new alternative mapping. Do not switch to intensity, pulse, duration, or interval merely because a previous analysis mentioned feedback burden. Exception: if the researcher is asking to update existing mapping ID 140, only minintensity and/or maxintensity may change; threshold changes must be framed as a new alternative mapping, not an update to mapping 140.'
      : requestedBasis === 'feedback_burden_or_noticeability'
        ? 'When the researcher asks about feedback burden, intrusiveness, strength, or noticeability, primarily change haptic delivery criteria such as intensity, pulses, duration, or interval, while preserving sensor thresholds unless the value distribution also justifies threshold changes. For updates to mapping ID 140, only minintensity and/or maxintensity may change.'
        : 'Choose the changed criteria from the supplied evidence and the researcher request. If the current mapping already fits the recent values and no burden or noticeability issue is supported, it is acceptable to return no proposals and explain that no mapping change is supported. For updates to mapping ID 140, only minintensity and/or maxintensity may change.'
};

if (totalReadings === 0) {
  warnings.push(
    'No recent sensor readings were found for the selected scope. Proposals must therefore be treated as conceptual drafts.'
  );
}

return [{
  json: {
    session_id: request.session_id,
    message: request.message,

    usecase_id:
      Number(row.usecase_id ?? request.usecase_id),

    usecase_name:
      row.usecase_name ??
      request.usecase_name ??
      null,

    user_id: request.user_id,
    user_mapping_id: request.user_mapping_id,

    context: request.context ?? {},

    current_mappings:
      Array.isArray(currentMappings)
        ? currentMappings
        : [],

    sensor_statistics: sensorStatistics ?? {},

    mapping_adjustment_guidance:
      mappingAdjustmentGuidance,

    selected_user_mapping:
      selectedUserMapping &&
      typeof selectedUserMapping === 'object'
        ? selectedUserMapping
        : null,

    context_warnings: warnings
  }
}];

const raw = $input.first().json ?? {};

const context =
  $('Package Mapping Design Context').first().json ?? {};

/**
 * Helpers
 */
function parseJsonValue(value, fallback) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return fallback;
  }

  if (typeof value === 'object') {
    return value;
  }

  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}

function parseModelResponse(value) {
  if (
    value &&
    typeof value === 'object' &&
    !Array.isArray(value)
  ) {
    return value;
  }

  let text = String(value ?? '').trim();

  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    return JSON.parse(text);
  } catch {
    return {
      reply: text,
      warnings: [
        'The Mapping Design Expert did not return valid structured JSON.'
      ],
      proposals: [],
      recommended_actions: []
    };
  }
}

function arrayValue(value) {
  const parsed = parseJsonValue(value, []);

  return Array.isArray(parsed)
    ? parsed
    : [];
}

function objectValue(value) {
  const parsed = parseJsonValue(value, {});

  return (
    parsed &&
    typeof parsed === 'object' &&
    !Array.isArray(parsed)
  )
    ? parsed
    : {};
}

function objectArray(value) {
  return arrayValue(value).filter(
    item =>
      item &&
      typeof item === 'object' &&
      !Array.isArray(item)
  );
}

function stringArray(value) {
  return arrayValue(value)
    .filter(
      item =>
        item !== null &&
        item !== undefined &&
        String(item).trim() !== ''
    )
    .map(item => String(item).trim());
}

function numberOrNull(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const number = Number(value);

  return Number.isFinite(number)
    ? number
    : null;
}

/**
 * Parse the Basic LLM Chain result.
 */
const candidate =
  raw.text ??
  raw.output ??
  raw.response ??
  raw.answer ??
  raw.result ??
  raw.reply ??
  raw;

const parsed =
  parseModelResponse(candidate);

/**
 * Read deterministic context produced before the LLM.
 */
const currentMappings =
  arrayValue(context.current_mappings);

const sensorStatistics =
  objectValue(context.sensor_statistics);


const selectedUserMapping =
  context.selected_user_mapping &&
  typeof context.selected_user_mapping === 'object' &&
  !Array.isArray(context.selected_user_mapping)
    ? context.selected_user_mapping
    : null;

const selectedMapping =
  selectedUserMapping?.mapping &&
  typeof selectedUserMapping.mapping === 'object' &&
  !Array.isArray(selectedUserMapping.mapping)
    ? selectedUserMapping.mapping
    : null;

/**
 * Extract database identifiers.
 */
const currentMappingIds = [
  ...new Set(
    currentMappings
      .map(mapping =>
        numberOrNull(mapping?.id)
      )
      .filter(id => id !== null)
  )
];

const selectedMappingId =
  numberOrNull(
    selectedMapping?.id ??
    selectedUserMapping?.mapping_id
  );

const selectedAssignmentId =
  numberOrNull(
    selectedUserMapping?.assignment_id
  );

const usecaseId =
  numberOrNull(context.usecase_id);

const userId =
  numberOrNull(context.user_id);

const totalReadings =
  Number(
    sensorStatistics.total_readings ?? 0
  );

/**
 * Build trustworthy database references.
 *
 * Model-generated source_refs are intentionally ignored.
 */
const evidenceRefs = [];

if (currentMappingIds.length > 0) {
  evidenceRefs.push({
    type: 'database_context',
    source: 'feedback_config_rules',
    reference:
      `Active use-case mapping IDs used for comparison: ${currentMappingIds.join(', ')}`
  });
}

if (selectedMappingId !== null) {
  evidenceRefs.push({
    type: 'database_context',
    source: 'User_UC_Mappings',
    reference:
      `Selected participant's current mapping ID: ${selectedMappingId}` +
      (
        selectedAssignmentId !== null
          ? `; assignment ID: ${selectedAssignmentId}`
          : ''
      )
  });
}

if (totalReadings > 0) {
  evidenceRefs.push({
    type: 'database_context',
    source: 'SensorData',
    reference:
      `Recent ${Number(sensorStatistics.window_days ?? 30)}-day sample: ` +
      `${totalReadings} readings; observed range ` +
      `${sensorStatistics.min_seen ?? 'unknown'}-` +
      `${sensorStatistics.max_seen ?? 'unknown'}`
  });
}

/**
 * Build top-level deterministic citations.
 */
const citations = [];

const allMappingIds = [
  ...new Set([
    ...currentMappingIds,
    ...(
      selectedMappingId !== null
        ? [selectedMappingId]
        : []
    )
  ])
];

if (allMappingIds.length > 0) {
  citations.push({
    type: 'database',
    source: 'feedback_config_rules',
    record_ids: allMappingIds,
    usecase_id: usecaseId,
    expert: 'mapping_design'
  });
}

if (
  selectedAssignmentId !== null ||
  selectedMappingId !== null
) {
  citations.push({
    type: 'database',
    source: 'User_UC_Mappings',
    assignment_id: selectedAssignmentId,
    user_id: userId,
    mapping_id: selectedMappingId,
    usecase_id: usecaseId,
    expert: 'mapping_design'
  });
}

if (totalReadings > 0) {
  citations.push({
    type: 'database',
    source: 'SensorData',
    usecase_id: usecaseId,
    user_id: userId,
    window_days:
      Number(
        sensorStatistics.window_days ?? 30
      ),
    total_readings: totalReadings,
    expert: 'mapping_design'
  });
}

/**
 * Validate proposals.
 */
const requiredParamNames = [
  'minvalue',
  'maxvalue',
  'minpulses',
  'maxpulses',
  'minintensity',
  'maxintensity',
  'minduration',
  'maxduration',
  'mininterval',
  'maxinterval'
];

const hapticParamNames = [
  'minpulses',
  'maxpulses',
  'minintensity',
  'maxintensity',
  'minduration',
  'maxduration',
  'mininterval',
  'maxinterval'
];

const validationWarnings = [];

const proposals =
  objectArray(parsed.proposals)
    .slice(0, 3)
    .map((proposal, index) => {
      const proposalId =
        `p${index + 1}`;

      const rawParams =
        proposal?.params &&
        typeof proposal.params === 'object' &&
        !Array.isArray(proposal.params)
          ? proposal.params
          : {};

      const params = {};

      for (const name of requiredParamNames) {
        params[name] =
          numberOrNull(rawParams[name]);
      }

      const proposalWarnings =
        stringArray(proposal?.warnings);

      const missingParams =
        requiredParamNames.filter(
          name => params[name] === null
        );

      if (missingParams.length > 0) {
        const warning =
          `${proposalId} is missing numeric parameters: ` +
          `${missingParams.join(', ')}.`;

        proposalWarnings.push(warning);
        validationWarnings.push(warning);
      }

      if (
        params.minvalue !== null &&
        params.maxvalue !== null &&
        params.minvalue >= params.maxvalue
      ) {
        const warning =
          `${proposalId} has an invalid sensor range: ` +
          'minvalue must be lower than maxvalue.';

        proposalWarnings.push(warning);
        validationWarnings.push(warning);
      }

      const negativeParams =
        hapticParamNames.filter(
          name =>
            params[name] !== null &&
            params[name] < 0
        );

      if (negativeParams.length > 0) {
        const warning =
          `${proposalId} contains negative haptic parameters: ` +
          `${negativeParams.join(', ')}.`;

        proposalWarnings.push(warning);
        validationWarnings.push(warning);
      }

      return {
        proposal_id: proposalId,

        label:
          String(
            proposal?.label ??
            `Mapping option ${index + 1}`
          ).trim(),

        params,

        rationale:
          String(
            proposal?.rationale ?? ''
          ).trim(),

        tradeoffs:
          stringArray(proposal?.tradeoffs),

        warnings: [
          ...new Set(proposalWarnings)
        ],

        /**
         * Always use deterministic references,
         * not the model-generated references.
         */
        source_refs:
          evidenceRefs.map(
            reference => ({ ...reference })
          )
      };
    });

/**
 * Normalize recommended actions.
 */
const validProposalIds =
  new Set(
    proposals.map(
      proposal => proposal.proposal_id
    )
  );

const modelActions =
  objectArray(
    parsed.recommended_actions ??
    parsed.recommendedActions ??
    parsed.actions
  );

const actionsByProposal =
  new Map();

for (const action of modelActions) {
  const proposalId =
    String(
      action?.proposal_id ?? ''
    ).trim();

  if (
    !proposalId ||
    !validProposalIds.has(proposalId) ||
    actionsByProposal.has(proposalId)
  ) {
    continue;
  }

  actionsByProposal.set(
    proposalId,
    {
      action:
        String(
          action.action ??
          'review_proposal'
        ).trim(),

      proposal_id: proposalId,

      label:
        String(
          action.label ??
          'Review this draft'
        ).trim()
    }
  );
}

/**
 * Guarantee one action for every proposal.
 */
for (const proposal of proposals) {
  if (!actionsByProposal.has(proposal.proposal_id)) {
    actionsByProposal.set(
      proposal.proposal_id,
      {
        action: 'review_proposal',
        proposal_id: proposal.proposal_id,
        label: 'Review this draft'
      }
    );
  }
}

const recommendedActions =
  [...actionsByProposal.values()];

/**
 * Normalize warnings.
 */
const allWarnings = [
  ...stringArray(context.context_warnings),
  ...stringArray(parsed.warnings),
  ...validationWarnings
];

/**
 * Warn when the current participant mapping has
 * an incomplete sensor range.
 */
if (
  selectedMapping &&
  (
    selectedMapping.minvalue === null ||
    selectedMapping.minvalue === undefined ||
    selectedMapping.maxvalue === null ||
    selectedMapping.maxvalue === undefined
  )
) {
  allWarnings.push(
    `The selected participant's mapping ${selectedMappingId ?? ''} ` +
    'does not define a complete sensor-value range.'
  );
}

const hasMissingSensorWarning =
  totalReadings === 0 ||
  allWarnings.some(warning =>
    /no recent sensor readings/i.test(warning)
  );

const warnings = [
  ...new Set(
    allWarnings
      .filter(Boolean)
      .map(String)
      .filter(
        warning =>
          !/no recent sensor readings/i.test(warning)
      )
  )
];

if (hasMissingSensorWarning) {
  warnings.unshift(
    'No recent sensor readings were found for the selected scope. ' +
    'These proposals are conceptual drafts and are not based on ' +
    'recent participant sensor data.'
  );
}

/**
 * Construct the reply.
 */
let reply =
  String(
    parsed.reply ??
    parsed.answer ??
    parsed.message ??
    ''
  ).trim();

if (!reply) {
  reply =
    proposals.length > 0
      ? `I prepared ${proposals.length} read-only mapping draft proposals.`
      : 'The Mapping Design Expert could not prepare valid mapping proposals.';
}

/**
 * Avoid language that implies database persistence.
 */
reply = reply
  .replace(
    /\b(?:have|has)\s+been\s+created\b/gi,
    'are presented'
  )
  .replace(
    /\bwere\s+created\b/gi,
    'are presented'
  )
  .replace(
    /\bcreated\s+for\s+review\b/gi,
    'presented for review'
  );

const statesNoMutation =
  /nothing was saved|not saved|nothing was assigned|not assigned|nothing was changed|no changes were made|read-only/i
    .test(reply);

if (!statesNoMutation) {
  reply +=
    '\n\nNothing was saved, assigned, activated, or changed.';
}

const success =
  parsed.success !== false &&
  proposals.length > 0 &&
  validationWarnings.length === 0;

return [{
  json: {
    expert: 'mapping_design',
    success,
    reply,

    session_id:
      context.session_id ?? null,

    citations,
    warnings,
    proposals,

    recommended_actions:
      recommendedActions
  }
}];
